    private RadBands() {}

    /** Bilinear (T,p) interpolation with clamping. Missing entries are 0. */
    public static double kappa(int gas, int band, double tK, double pMb) {
        double t = Math.max(TS[0], Math.min(TS[TS.length - 1], tK));
        double p = Math.max(PS[0], Math.min(PS[PS.length - 1], pMb));
        int ti = 0; while (ti < TS.length - 2 && t > TS[ti + 1]) ti++;
        int pi = 0; while (pi < PS.length - 1 && p < PS[pi]) pi++;
        int pi2 = Math.min(pi + 1, PS.length - 1); if (pi > 0) pi = pi2 - 1;
        double wt = (t - TS[ti]) / (TS[ti + 1] - TS[ti]);
        double wp = (p - PS[pi]) / (PS[pi2] - PS[pi]);
        double k00 = KAPPA[gas][band][ti][pi], k01 = KAPPA[gas][band][ti][pi2];
        double k10 = KAPPA[gas][band][ti + 1][pi], k11 = KAPPA[gas][band][ti + 1][pi2];
        return (1 - wt) * ((1 - wp) * k00 + wp * k01) + wt * ((1 - wp) * k10 + wp * k11);
    }
    private static final int NT_P = 41;
    private static final double T0_P = 150.0, DT_P = 5.0;
    private static final double[][] FRAC = new double[NT_P][BANDS.length];
    private static final double HC_K = 1.4387769;
    static {
        for (int i = 0; i < NT_P; i++) {
            double T = T0_P + DT_P * i;
            for (int b = 0; b < BANDS.length; b++) {
                FRAC[i][b] = blackbodyFrac(HC_K * BANDS[b][1] / T)
                           - blackbodyFrac(HC_K * BANDS[b][0] / T);
            }
        }
    }
    /** 0..x blackbody fraction (x = hc*nu/kT). */
    private static double blackbodyFrac(double x) {
        if (x <= 0.0) return 0.0;
        double s = 0.0;
        for (int n = 1; n <= 80; n++) {
            double e = Math.exp(-n * x);
            s += e * (x * x * x / n + 3.0 * x * x / (n * n) + 6.0 * x / (n * n * n)
                    + 6.0 / (n * n * n * n));
            if (e < 1.0e-17) break;
        }
        return 1.0 - 15.0 / Math.pow(Math.PI, 4) * s;
    }
    /** band b Planck integral [W/m2/sr]. */
    public static double planckBand(int b, double T) {
        double x = (T - T0_P) / DT_P;
        int i = (int) Math.floor(x);
        if (i < 0) i = 0;
        if (i > NT_P - 2) i = NT_P - 2;
        double w = x - i;
        double f = (1.0 - w) * FRAC[i][b] + w * FRAC[i + 1][b];
        return 5.670374419e-8 * Math.pow(T, 4) * f;
    }
